5	/**
6	 * A derived, opaque summary of an owner's contact identity: the canonical telephone, the canonical
7	 * email (empty when absent) and the household id, joined by '|'.
8	 * {@link org.springframework.samples.petclinic.mapper.OwnerMapper} returns it on the response so a
9	 * client can compare owners at a glance. Duplicate detection itself keys off the household id alone
10	 * (see {@link EnsureUniqueIdentity}); this value simply surfaces the parts. Not a pipeline step, so it
11	 * exposes plain helpers.
12	 */
13	public final class IdentityKey {
14	
15	    private IdentityKey() {
16	    }
17	
18	    /** The identity key of an existing or freshly built owner. */
19	    public static String forOwner(Owner owner) {
20	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
21	    }
22	
23	    /**
24	     * Builds the identity key from its parts: the telephone in canonical E.164 form (see
25	     * {@link TelephoneNormalizer}), the email lower-cased or empty when absent or blank (see
26	     * {@link EmailNormalizer}) and the household id or empty when absent, separated by '|'.
27	     */
28	    public static String of(String telephone, String email, String householdId) {
29	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|" + orEmpty(householdId);
30	    }
31	
32	    private static String normalizeTelephone(String telephone) {
33	        String e164 = TelephoneNormalizer.toE164(telephone);
34	        return e164 == null ? orEmpty(telephone) : e164;
35	    }
36	
37	    private static String normalizeEmail(String email) {
38	        return (email == null || email.isBlank()) ? "" : EmailNormalizer.normalize(email);
39	    }
40	
41	    private static String orEmpty(String value) {
42	        return value == null ? "" : value;
43	    }
44	}
