package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.section.clazz.Flow;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Entry step of the create pipeline. When the request carries an {@code Idempotency-Key} that has
 * already created an owner (see {@link IdempotencyStore}), it diverts to the {@code existing} output
 * to replay that owner with 200, short-circuiting the create so the request never reaches the
 * duplicate checks (which would otherwise reject the repeat with 409). With no key, or a key not seen
 * before, it falls through to {@code next} and the normal create runs; {@link RecordIdempotencyKey}
 * then registers the key once the owner is saved.
 */
public class CheckIdempotency {

    /** Branch taken for a repeated key: replays the owner the key first created, by its id. */
    @FunctionalInterface
    public interface ExistingOwnerFlow {
        void replay(Integer ownerId);
    }

    public void service(
            @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
            IdempotencyStore idempotencyStore, @Flow("existing") ExistingOwnerFlow existing) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            return;
        }
        idempotencyStore.lookup(idempotencyKey).ifPresent(existing::replay);
    }
}

